  "faqItems": [
    {
      "question": "What is Eos Backup and Battery?",
      "answer": "Eos is a whole-home battery backup brand for Houston-area homeowners with one main site architecture for plans, compare, learn, locations, and estimate routing.",
      "category": "Company & Positioning"
    },
    {
      "question": "Are you locked into one hardware platform forever?",
      "answer": "No. The platform is standardized because it fits the current methodology, not because the site is obligated to pretend alternatives do not exist.",
      "category": "Company & Positioning"
    },
    {
      "question": "What plan sizes do you offer?",
      "answer": "The current canonical lineup runs from Essential through Ultimate, plus the V2X add-on.",
      "category": "Products & Plans"
    },
    {
      "question": "Do I need solar to use a battery?",
      "answer": "No. A battery system can work as grid-tied backup without solar panels.",
      "category": "Products & Plans"
    },
    {
      "question": "Can I add more capacity later?",
      "answer": "Yes. The platform is positioned around modular growth rather than forcing buyers to replace everything to expand.",
      "category": "Products & Plans"
    },
    {
      "question": "Why is installation quoted separately?",
      "answer": "Because every home is different enough that bundled pricing often hides the actual scope and makes comparison worse.",
      "category": "Pricing & Payment"
    },
    {
      "question": "Is financing available?",
      "answer": "Yes. Financing remains part of the estimate conversation for buyers who do not want to pay the full equipment cost upfront.",
      "category": "Pricing & Payment"
    },
    {
      "question": "Are generators still valid for some homeowners?",
      "answer": "Yes. The site keeps saying that explicitly because honest category comparison builds more trust than pretending generators never fit.",
      "category": "Comparison"
    },
    {
      "question": "What happens after I submit an estimate request?",
      "answer": "The intake gets routed based on plan sizing, generator-alternative logic, or broader comparison help so the next step matches the buyer’s real intent.",
      "category": "Process"
    },
    {
      "question": "Why is there a dedicated permits and HOA guide?",
      "answer": "Because permits and property restrictions materially affect fit, especially in HOA-heavy neighborhoods, and they should stay easy to find.",
      "category": "Permits & HOA"
    }
  ],
